input.command:
cd /tmp/claude-0/-home-user-VascularColoring/ff48e98c-095a-5fc4-948c-c18af8e8e96e/scratchpad && python3 -c "
import json
with open('issue-358.jsonl') as f:
    lines = f.readlines()
for i, l in enumerate(lines):
    d = json.loads(l)
    t = d.get('type')
    ts = d.get('timestamp','')
    if t == 'user' or t == 'assistant':
        msg = d.get('message', {})
        role = msg.get('role')
        content = msg.get('content')
        summary=''
        if isinstance(content, str):
            summary = content[:200]
        elif isinstance(content, list):
            parts=[]
            for c in content:
                ctype = c.get('type')
                if ctype == 'text':
                    parts.append('TEXT:'+c.get('text','')[:150])
                elif ctype == 'tool_use':
                    parts.append('TOOL_USE:'+c.get('name','')+' '+json.dumps(c.get('input',{}))[:150])
                elif ctype == 'tool_result':
                    cc = c.get('content')
                    if isinstance(cc, list):
                        cc = ' '.join(x.get('text','')[:100] for x in cc if isinstance(x,dict))
                    parts.append('TOOL_RESULT:'+str(cc)[:150])
            summary = ' | '.join(parts)
        print(f'{i} [{ts}] {role}: {summary}')
    else:
        print(f'{i} [{ts}] type={t} operation={d.get(\"operation\")}')
"

